import Navbar from "@/components/Navbar";

async function getBlog(slug: string) {
  try {
    const res = await fetch(
      `http://65.2.124.237:8000/api/v1/users/blog/${slug}`,
      { cache: "no-store" }
    );

    const json = await res.json();
    return json.data?.blog || null;
  } catch {
    return null;
  }
}

export default async function BlogPostPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;

  const blog = await getBlog(slug);

  if (!blog) {
    return (
      <>
        <Navbar />
        <div className="pt-40 text-center text-white text-3xl">
          Blog not found.
        </div>
      </>
    );
  }

  return (
    <>
      <Navbar />
      <div className="pt-32 px-6 md:px-16 text-white max-w-3xl mx-auto">

        {/* BLOG TITLE */}
        <h1 className="text-5xl font-bold mb-6">{blog.title}</h1>

        {/* BLOG DATE */}
        <p className="text-cyan-400 mb-10">
          {new Date(blog.publishDate).toLocaleDateString("en-US", {
            month: "long",
            day: "numeric",
            year: "numeric",
          })}
        </p>

        {/* BLOG IMAGE */}
        {blog.images?.[0]?.url && (
          <img
            src={blog.images[0].url}
            alt=""
            className="w-full rounded-xl mb-10"
          />
        )}

        {/* BLOG CONTENT — EXACTLY LIKE API */}
        <div
          className="prose prose-invert max-w-none leading-relaxed text-lg"
          dangerouslySetInnerHTML={{
            __html: blog.content || blog.shortDescription,
          }}
        />
      </div>
    </>
  );
}
